from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Optimized TRMM kernel.
#
# Mathematical operation (same as the original PolyBench kernel):
#   B := alpha * A^T * B_in
# where:
#   - A is M×M, unit lower-triangular (A[k, i] = 0 for k < i, A[i, i] = 1),
#   - B_in is the input matrix stored in B on entry.
#
# The original Exo kernel was:
#   for i in [0, m):
#     for j in [0, n):
#       for k in [i+1, m):
#         B[i, j] += A[k, i] * B[k, j]
#       B[i, j] = alpha * B[i, j]
#
# We instead use an outer-product style triangular update:
#
#   for k in [0, m):
#     for i in [0, k):
#       for j in [0, n):
#         B[i, j] += A[k, i] * B[k, j]
#   for i, j:
#     B[i, j] *= alpha
#
# This is algebraically equivalent:
#   - Each pair (i, k) with k > i contributes exactly once to B[i, j].
#   - During the triangular phase, row k of B is never written, only read,
#     so B[k, j] is always the original B_in[k, j].
#   - The final scaling by alpha happens after all additions, yielding
#       B[i, j] = alpha * ( B_in[i, j] + sum_{k > i} A[k, i] * B_in[k, j] ).
#
# Compared to the original i–j–k nest, this order improves data locality:
#   - For each k, we walk B[k, :] in j once and reuse it for all rows i < k.
#   - B is row-major, so j is kept innermost for unit-stride accesses.
#   - We additionally tile j with a fixed tile size (64) to keep a
#     64-column panel of B[i, :] and B[k, :] hot in the caches.
#
# A and B remain row-major as in the C driver; no changes to the C layout
# or initialization are required.

@proc
def kernel_trmm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Triangular outer-product update:
    #   for k in [0, m):
    #     for i in [0, k):
    #       B[i, :] += A[k, i] * B[k, :]
    # implemented with explicit tiling in the column (j) dimension.

    for k in seq(0, m):
        # Only rows strictly above k (i < k) receive contributions from row k.
        for i in seq(0, k):
            # Hoist A[k, i] into a scalar so we only load it once per (k, i).
            a_ki: DATA_TYPE
            a_ki = A[k, i]

            # Manually tile the column dimension j with a tile size of 64.
            # Outer loop jj walks tiles; inner loop j iterates within a tile.
            # Guard ensures we do not read/write past n when n is not
            # a multiple of 64.
            for jj in seq(0, (n + 63) / 64):
                for j in seq(0, 64):
                    if 64 * jj + j < n:
                        B[i, 64 * jj + j] += a_ki * B[k, 64 * jj + j]

    # Final scaling pass: B[i, j] *= alpha
    # This is separated from the triangular update to:
    #   - keep the triangular phase purely additive (better for reordering),
    #   - enable an easy, highly parallel row-wise scaling kernel.
    for i in seq(0, m):
        for jj in seq(0, (n + 63) / 64):
            for j in seq(0, 64):
                if 64 * jj + j < n:
                    B[i, 64 * jj + j] = alpha * B[i, 64 * jj + j]


# Scheduling pass:
#   - parallelize the outer loop of the final scaling pass over i.
#     Each row B[i, :] is independent at this point.
#   - run Exo's simplifier,
#   - rename to the externally visible kernel name "kernel_trmm".
def schedule_kernel_trmm():
    p = kernel_trmm_base

    # There are two "for i" loops:
    #   1) inside the triangular update (nested under k),
    #   2) the outer loop of the final scaling pass.
    # We want to parallelize the second one.
    i_loops = p.find_all("for i in _:_")
    scale_i = i_loops[1]

    # Parallelize scaling over rows of B; this typically lowers to OpenMP.
    p = parallelize_loop(p, scale_i)

    # Allow Exo to simplify expressions and clean up any dead code.
    p = simplify(p)

    # Use the externally expected name "kernel_trmm".
    p = rename(p, "kernel_trmm")
    return p


# Optimized kernel that will be compiled and called from C.
kernel_trmm = schedule_kernel_trmm()
